import { describe, expect, it } from "vitest";
import { scopeSvg } from "./svg-scope.js";

// Trimmed from dvisvgm 2.13.1 output in DVI mode with --font-format=woff2.
const svgWithFonts = `<?xml version='1.0' encoding='UTF-8'?>
<!-- This file was generated by dvisvgm 2.13.1 -->
<svg version='1.1' xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink' width='54pt' height='9pt' viewBox='0 -9 54 9'>
<style type='text/css'>
<![CDATA[@font-face{font-family:cmmi10;src:url(data:application/x-font-woff2;base64,AAAA) format('woff2');}
@font-face{font-family:cmr10;src:url(data:application/x-font-woff2;base64,BBBB) format('woff2');}
text.f0 {font-family:cmmi10;font-size:9.96264px}
text.f1 {font-family:cmr10;font-size:9.96264px}
]]>
</style>
<g id='page1'>
<text class='f1' x='0' y='0'>Hello</text>
<text class='f0' x='20' y='0'>x</text>
</g>
</svg>`;

// Trimmed from dvisvgm output with glyphs as paths and a TikZ clip.
const svgWithReferences = `<svg version='1.1' xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink' width='10pt' height='10pt' viewBox='0 0 10 10'>
<defs>
<path id='g0-65' d='M0 0L1 1Z'/>
<clipPath id='clip1'><path d='M0 0H5V5Z'/></clipPath>
</defs>
<g id='page1' clip-path='url(#clip1)'>
<use x='1' y='2' xlink:href='#g0-65'/>
<use x='3' y='2' href='#g0-65'/>
</g>
</svg>`;

describe("scopeSvg", () => {
  it("drops the XML prolog so the SVG can sit inside HTML", () => {
    const scoped = scopeSvg(svgWithFonts, "t-abc-");

    expect(scoped.startsWith("<svg")).toBe(true);
  });

  it("prefixes class names in both the markup and the style rules", () => {
    const scoped = scopeSvg(svgWithFonts, "t-abc-");

    expect(scoped).toContain("<text class='t-abc-f1' x='0' y='0'>Hello</text>");
    expect(scoped).toContain("text.t-abc-f0 {font-family:t-abc-cmmi10;");
    expect(scoped).not.toMatch(/class='f\d'/);
    expect(scoped).not.toMatch(/text\.f\d\b/);
  });

  it("prefixes font families, since two diagrams embed different subsets of the same font", () => {
    const scoped = scopeSvg(svgWithFonts, "t-abc-");

    expect(scoped).toContain("@font-face{font-family:t-abc-cmmi10;");
    expect(scoped).toContain("@font-face{font-family:t-abc-cmr10;");
    expect(scoped).not.toMatch(/font-family:cm/);
  });

  it("prefixes ids along with every reference to them", () => {
    const scoped = scopeSvg(svgWithReferences, "t-abc-");

    expect(scoped).toContain("<path id='t-abc-g0-65'");
    expect(scoped).toContain("<clipPath id='t-abc-clip1'>");
    expect(scoped).toContain(
      "<g id='t-abc-page1' clip-path='url(#t-abc-clip1)'>",
    );
    expect(scoped).toContain("xlink:href='#t-abc-g0-65'");
    expect(scoped).toContain("<use x='3' y='2' href='#t-abc-g0-65'/>");
  });

  it("leaves path data and text content alone", () => {
    const scoped = scopeSvg(svgWithReferences, "t-abc-");

    expect(scoped).toContain("d='M0 0L1 1Z'");
  });
});
